# Check GSD manifest for what it considers active files
python3 -c "
import json
with open('$HOME/.config/opencode/gsd-file-manifest.json') as f:
    data = json.load(f)
files = data.get('files', data.get('entries', data.get('manifest', [])))
if isinstance(files, list):
    print(f'Total entries: {len(files)}')
    # Count by directory prefix
    from collections import Counter
    prefixes = Counter()
    for f in files:
        if isinstance(f, str):
            for p in ['opencode/opencode', 'opencode/agents', 'opencode/command', 'opencode/gsd-core', 'opencode/skills']:
                if p in f:
                    prefixes[p] += 1
                    break
            else:
                prefixes['other'] += 1
    for p, c in prefixes.most_common():
        print(f'  {p}: {c}')
else:
    print(type(files))
    print(str(files)[:500])
" 2>/dev/null || echo "Could not parse manifest"

